const subscribers = $input.all();
const segments = {
  vip: [],
  regular: [],
  new_subscriber: [],
  inactive: []
};

for (const sub of subscribers) {
  const tags = (sub.json.Tags || '').toLowerCase();
  const status = (sub.json.Status || '').toLowerCase();

  if (status !== 'active') continue;

  if (tags.includes('vip')) {
    segments.vip.push(sub.json);
  } else if (tags.includes('new')) {
    segments.new_subscriber.push(sub.json);
  } else if (tags.includes('inactive')) {
    segments.inactive.push(sub.json);
  } else {
    segments.regular.push(sub.json);
  }
}

return Object.entries(segments).map(([segment, subs]) => ({
  json: {
    segment,
    subscriberCount: subs.length,
    subscribers: subs,
    scheduledAt: new Date().toISOString()
  }
}));

const segment = $input.first().json;
const templates = {
  vip: {
    subject: '🌟 Exclusive VIP Offer Just for You',
