const template = templates[segment.segment] || templates.regular;
const sendHour = { vip: 10, regular: 11, new_subscriber: 14, inactive: 18 };

return [{
  json: {
    ...segment,
    emailSubject: template.subject,
    emailBody: template.body,
    optimalSendHour: sendHour[segment.segment] || 11
  }
}];

const data = $input.first().json;
const results = [];
const batchSize = 10;
const delayMs = 2000;

for (let i = 0; i < data.subscribers.length; i++) {
  const sub = data.subscribers[i];
  results.push({
    email: sub.Email,
    name: sub.Name || 'Valued Customer',
    segment: data.segment,
    subject: data.emailSubject,
    body: data.emailBody,
    batchNumber: Math.floor(i / batchSize) + 1,
    sendOrder: i + 1
  });
}

return results.map(r => ({ json: r }));
